// Courts visual baselines (#425): every viewport × theme project (360/768/1280, light and dark)
// with the clock frozen: the index, the A1 forum with the degraded banner on each detail tab, the
// A0 forum (empty halls, an adapter without a version), the planned (disabled) forums, the
// degraded card, the empty index and the error state. Baselines live in e2e/__screenshots__ and
// are only ever generated by the e2e workflow's `update_snapshots` dispatch in the pinned
// Playwright image (see e2e/README.md); without one the test is skipped.
import { existsSync } from 'node:fs';

import type { Locator, Page, TestInfo } from '@playwright/test';

import type { AsUser } from '../../fixtures/auth.ts';
import { expect, test } from '../../fixtures/index.ts';
import { A0_FORUM, COURTS_WORKSPACE, DEGRADED_FORUM } from '../../fixtures/courts-data.ts';

import { courtsPath, emptyCatalogue, openCourts } from './helpers.ts';

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

interface Shot {
  name: string;
  /** `database` is the worker database. Returns the element to shoot, or the page. */
  setUp: (page: Page, asUser: AsUser, database: string) => Promise<Locator | null>;
}

const SHOTS: readonly Shot[] = [
  {
    name: 'courts-index.png',
    setUp: async (page, asUser) => {
      await openCourts(page, asUser);
      return null;
    },
  },
  {
    name: 'courts-degraded-card.png',
    setUp: async (page, asUser) => {
      await openCourts(page, asUser);
      return page.locator('main').locator(`[data-forum-card="${DEGRADED_FORUM}"]`);
    },
  },
  {
    name: 'courts-planned.png',
    setUp: async (page, asUser) => {
      await openCourts(page, asUser);
      return page.locator('[data-courts-planned]');
    },
  },
  ...(['halls', 'adapter', 'links'] as const).map((tab) => ({
    name: `courts-forum-a1-${tab}.png`,
    setUp: async (page: Page, asUser: AsUser) => {
      await openCourts(page, asUser, { path: courtsPath(DEGRADED_FORUM, tab) });
      return null;
    },
  })),
  ...(['halls', 'adapter'] as const).map((tab) => ({
    name: `courts-forum-a0-${tab}.png`,
    setUp: async (page: Page, asUser: AsUser) => {
      await openCourts(page, asUser, { path: courtsPath(A0_FORUM, tab) });
      return null;
    },
  })),
  {
    name: 'courts-empty.png',
    setUp: async (page, asUser, database) => {
      await emptyCatalogue(database);
      await openCourts(page, asUser);
      await expect(page.locator('main [data-pattern-state="empty"]')).toBeVisible();
      return null;
    },
  },
  {
    name: 'courts-error.png',
    setUp: async (page, asUser) => {
      await openCourts(page, asUser);
      await page.goto(`/w/${COURTS_WORKSPACE}/courts?__state=error`);
      await expect(page.locator('main').getByText('Could not load courts.')).toBeVisible({
        timeout: 15_000,
      });
      return null;
    },
  },
];

test.describe('courts visual baselines', () => {
  for (const shot of SHOTS) {
    test(
      shot.name.replace(/\.png$/, ''),
      { tag: '@visual' },
      async ({ page, asUser, db }, testInfo) => {
        skipWithoutBaseline(testInfo, shot.name);
        const target = await shot.setUp(page, asUser, db.name);
        const options = { animations: 'disabled', caret: 'hide' } as const;
        if (target === null) await expect(page).toHaveScreenshot(shot.name, options);
        else await expect(target).toHaveScreenshot(shot.name, options);
      },
    );
  }
});
